// Источник: проверка #6a86f7ee5747 07.10.2026 17:55–17:56 (session.json test_data «בורא פרי העץ אשכנז»: «заменён тестовым текстом и утверждён,
// возвращён оригинал (7 полей = orig-haetz-ashkenaz.json)»), бриф .qa/research/6a86f7ee5747.md, кейс .qa/tests/admin/AD-06,
// скриншоты ee5747-repl-1-empty, -2-draft-admin, -2-draft-user1, -3-approved-admin, -3-new-text-user1, -5-restored-*.
// Тикеты #6a86f7ee5747 (ברכות, הושלם 07.10; условие пользователя — замена текста брахи в админке видна пользователю) + #a5decf4a.
// Опора: F-102 AC1 (неутверждённое не показывается), AC4 (исправление текста без новой версии приложения), AC5 (кто и когда);
// AD-06: после утверждения у пользователя новый текст и «מקור: … · אושר על ידי <имя>, <дата>».
// @data: в finally текст возвращается посимвольно (orig-haetz-ashkenaz.json), остальные поля сверяются, аккаунт — USER1.
import { expect } from '@wdio/globals';
import { byText, byTextContains, byTextMatches, scrollToText } from '../../helpers/ui.ts';
import { toHome } from '../../helpers/app.ts';
import {
  asAdmin, asUser1, backToUser1, openAdminPrayer, openSection, reopenSection, readBody, readField, setBody, saveDraft, approveDraft,
  historyEntry, restoreSectionText, origHaetz, qaMarker, openUserHaetz,
} from '../_lib/admin.ts';

const PRAYER = 'בורא פרי העץ', NUSACH = 'אשכנז', SECTION = 'בורא פרי העץ';
// Текст с огласовками, как 07.10 17:55 (ee5747-repl-3-new-text-user1).
const TEST_TEXT = 'בָּרוּךְ אַתָּה ה\' אֱלֹהֵינוּ מֶלֶךְ הָעוֹלָם בּוֹרֵא פְּרִי הָעֵץ. (בדיקת QA)';
const MARK = '(בדיקת QA)';

describe('Админка в приложении: замена текста ברכה', () => {
  afterEach(async () => { await toHome(); });

  it('AD-06 «בורא פרי העץ · נוסח אשכנז»: стереть → вставить текст с ניקוד → черновик (USER1 видит старый) → утвердить (USER1 видит новый + «אושר על ידי») → оригинал #6a86f7ee5747 #a5decf4a @data', async () => {
    const orig = origHaetz();
    try {
      await asAdmin();

      // 1. Админка → «בורא פרי העץ · נוסח אשכנז» → קטע «בורא פרי העץ»: исходные поля = сохранённым 07.10.
      await openAdminPrayer(PRAYER, NUSACH);
      await openSection(SECTION);
      expect(await readField('כותרת הקטע')).toBe(orig.title);
      expect(await readBody()).toBe(orig.body);

      // 2. Стереть текст → «חסר טקסט לקטע.» (ee5747-repl-1-empty); вставить текст с огласовками → «שמירת טיוטה».
      await setBody('');
      await expect(await scrollToText('חסר טקסט לקטע.')).toBeDisplayed();
      await setBody(TEST_TEXT);
      expect(await readBody()).toBe(TEST_TEXT);           // ניקוד сохраняется «בדיוק כפי שהוזנו»
      await saveDraft();

      // 3. USER1: у ברכה прежний текст, без «(בדיקת QA)» (F-102 AC1).
      await asUser1();
      await openUserHaetz();
      await expect(byTextContains('בּוֹרֵא פְּרִי הָעֵץ:')).toBeDisplayed();
      await expect(byTextContains(MARK)).not.toBeDisplayed();

      // 4. ADMIN: утвердить → статус «מאושר · …», в истории «בורא פרי העץ: נוסח חדש אושר על ידי …».
      await asAdmin();
      await reopenSection(PRAYER, NUSACH, SECTION);
      expect(await readBody()).toBe(TEST_TEXT);
      const m = qaMarker('ad06');
      await approveDraft(m);
      await expect(await historyEntry(m)).toHaveText(new RegExp(`${SECTION}: נוסח חדש אושר על ידי .+`));

      // 5. USER1: новый текст и строка «מקור: … · אושר על ידי <имя>, <дата>» (AD-06, F-102 AC4/AC5).
      await asUser1();
      await openUserHaetz();
      await expect(byTextContains(MARK)).toBeDisplayed();
      await scrollToText('אושר על ידי');
      await expect(byTextMatches('(?s)מקור: .*אושר על ידי .*\\d{1,2}\\.\\d{1,2}\\.\\d{4}.*')).toBeDisplayed();
      await expect(byText('חזרה לברכות')).toBeDisplayed();
    } finally {
      try {
        // 6. Вернуть оригинал посимвольно, утвердить; сверить остальные поля с orig-haetz-ashkenaz.json.
        await asAdmin().catch(() => {});
        await restoreSectionText(PRAYER, NUSACH, SECTION, orig.body, 'ad06');
        expect(await readField('כותרת הקטע')).toBe(orig.title);
        expect(await readField('קרדיט למקור')).toBe(orig.attribution);
        expect(await readField('הפניה במקור')).toBe(orig.ref);
        expect(await readField('מהדורה')).toBe(orig.version);
        expect(await readField('רישיון')).toBe(orig.license);
      } finally {
        await backToUser1();
      }
    }
  });
});
